import { Component } from 'react'
import { AddHomeStyle, AddToIosHome } from './index.style'
import { ADD_TO_HOME, IOS_ADD_TO_HOME, IOS_ADD_ICON } from '../../images/imageUrl'
import { gTagOnAddToHome } from './tagManager'
import Cookies from 'universal-cookie'
import { get } from 'lodash/object'
import CustomText from '../CustomText'
import { Row } from '../../commonStyle/index.style'
import { isIos, isInStandaloneMode } from '../../helpers/utility'
import { ADD_TO_HOME_COOKIE } from '../../constants/cookies'

const cookies = new Cookies()
class AddHomeScreen extends Component {
  constructor (props) {
    super(props)
    this.state = {
      isShow: false,
      isIosShow: false
    }
    this.beforeInstallPrompt = ''
    this.removeBeforeInstallPrompt = ''
  }

  componentDidMount () {
    this.setState({
      isIosShow: (cookies.get(ADD_TO_HOME_COOKIE) !== 'false') && isIos() && !isInStandaloneMode()
    })
    this.removeBeforeInstallPrompt = window.addEventListener('beforeinstallprompt', this.handlerAddPrompt)
    window.addEventListener('appinstalled', (evt) => {
      // this event is fired if app is installed from broser addToHomeScreen
      // also if app was intalled from the user interface
      console.info('App was installed')
    })
  }

  handlerAddPrompt = (e) => {
    // Prevent the mini-infobar from appearing on mobile
    e.preventDefault()
    // Stash the event so it can be triggered later.
    this.beforeInstallPrompt = e
    // Update UI notify the user they can install the PWA
    this.showInstallBtn(true)
  }

  showInstallBtn = (isShow) => {
    this.setState({
      isShow: (cookies.get(ADD_TO_HOME_COOKIE) !== 'false') && isShow
    })
    cookies.set(ADD_TO_HOME_COOKIE, 'false', {
      path: '/',
      maxAge: 60 * 60 * 24 // store for 1 month
    })
  }

  handleAddToHomeScreen = () => {
    // Show the install prompt
    this.beforeInstallPrompt.prompt()
    // Wait for the user to respond to the prompt
    this.beforeInstallPrompt.userChoice.then((choiceResult) => {
      if (choiceResult.outcome === 'accepted') {
        gTagOnAddToHome(get(this.props, 'agentDetails.phone_no', ''))
      } else {
        window.removeEventListener('beforeinstallprompt', this.handlerAddPrompt)
        this.showInstallBtn(false)
      }
    })
  }

  handleCloseIos = () => {
    this.setState({
      isIosShow: false
    })
    cookies.set(ADD_TO_HOME_COOKIE, 'false', {
      path: '/',
      maxAge: 60 * 60 * 24 // store for 1 month
    })
  }

  render () {
    return this.state.isIosShow
      ? (
        <AddToIosHome>
          <Row className='add-ios-content'>
            <Row className='ios-app-left'>
              <img className='ios-add-img' src={IOS_ADD_TO_HOME} alt='' />
              <CustomText size='13px' lineHeight={1.5}>
              Install PasarPolis Mitra on your iPhone:<br />
              tap&nbsp;&nbsp;<img src={IOS_ADD_ICON} alt='' />&nbsp;&nbsp;and then Add to Homescreen.
              </CustomText>
            </Row>
            <div className='close-add-to-home' onClick={this.handleCloseIos}>
              <i className='fa fa-times' />
            </div>
          </Row>
        </AddToIosHome>
      )
      : (this.state.isShow && (
        <AddHomeStyle>
          <div className='add-log-container' onClick={this.handleAddToHomeScreen}>
            <img src={ADD_TO_HOME} alt='' />
            <div className='add-home-text'>Add PasarPolis Mitra to Home Screen</div>
          </div>
          <div onClick={e => this.showInstallBtn(false)}>X</div>
        </AddHomeStyle>
      ))
  }
}

export default AddHomeScreen
